function required(name) {
  const value = String($env[name] || '').trim();
  if (!value) throw new Error(`Init & Validate Config: missing ${name}`);
  return value;
}

function parseJson(name, raw) {
  try { return JSON.parse(raw); }
  catch (error) { throw new Error(`Init & Validate Config: ${name} is not valid JSON`); }
}

const workspaceSlug = required('WORKSPACE_SLUG');
const planeApiKey = required('PLANE_API_KEY');
const openAiApiKey = required('OPENAI_API_KEY');
const telegramChatId = required('PLANE_DAILY_BRIEFING_TELEGRAM_CHAT_ID');
const project = parseJson('PLANE_PROJECT_DEV', required('PLANE_PROJECT_DEV'));
const recipients = parseJson(
  'PLANE_DAILY_BRIEFING_RECIPIENTS',
  required('PLANE_DAILY_BRIEFING_RECIPIENTS'),
);

if (!/^-\d+$/.test(telegramChatId)) {
  throw new Error('Init & Validate Config: PLANE_DAILY_BRIEFING_TELEGRAM_CHAT_ID must be a negative Telegram group id');
}
if (!project || typeof project !== 'object' || !String(project.uuid || '').trim()) {
  throw new Error('Init & Validate Config: PLANE_PROJECT_DEV.uuid is required');
}
if (!project.states || typeof project.states !== 'object') {
  throw new Error('Init & Validate Config: PLANE_PROJECT_DEV.states is required');
}
for (const stateName of ['backlog', 'todo', 'inProgress', 'inReview', 'done', 'cancelled']) {
  if (!String(project.states[stateName] || '').trim()) {
    throw new Error(`Init & Validate Config: PLANE_PROJECT_DEV.states.${stateName} is required`);
  }
}
if (!Array.isArray(recipients) || recipients.length === 0) {
  throw new Error('Init & Validate Config: PLANE_DAILY_BRIEFING_RECIPIENTS must be a non-empty array');
}

const seenPlaneIds = new Set();
const seenTelegramUsers = new Set();
const normalizedRecipients = recipients.map((recipient, index) => {
  if (!recipient || typeof recipient !== 'object' || Array.isArray(recipient)) {
    throw new Error(`Init & Validate Config: recipient ${index + 1} must be an object`);
  }
  const allowedKeys = new Set(['planeUserId', 'displayName', 'telegramUsername']);
  const unknownKeys = Object.keys(recipient).filter(key => !allowedKeys.has(key));
  if (unknownKeys.length) {
    throw new Error(`Init & Validate Config: recipient ${index + 1} has unsupported keys: ${unknownKeys.join(', ')}`);
  }
  const planeUserId = String(recipient.planeUserId || '').trim();
  const displayName = String(recipient.displayName || '').trim();
  const telegramUsername = String(recipient.telegramUsername || '').trim().replace(/^@+/, '');
  if (!planeUserId || !displayName || !telegramUsername) {
    throw new Error(`Init & Validate Config: recipient ${index + 1} requires planeUserId, displayName and telegramUsername`);
  }
  if (displayName.length > 120) {
    throw new Error(`Init & Validate Config: recipient ${index + 1} displayName exceeds 120 characters`);
  }
  if (!/^[A-Za-z0-9_]{5,32}$/.test(telegramUsername)) {
    throw new Error(`Init & Validate Config: recipient ${index + 1} has an invalid Telegram username`);
  }
  const planeKey = planeUserId.toLowerCase();
  const telegramKey = telegramUsername.toLowerCase();
  if (seenPlaneIds.has(planeKey)) {
    throw new Error(`Init & Validate Config: duplicate planeUserId at recipient ${index + 1}`);
  }
  if (seenTelegramUsers.has(telegramKey)) {
    throw new Error(`Init & Validate Config: duplicate telegramUsername at recipient ${index + 1}`);
  }
  seenPlaneIds.add(planeKey);
  seenTelegramUsers.add(telegramKey);
  return { planeUserId, displayName, telegramUsername: `@${telegramUsername}` };
});

return [{
  json: {
    workspaceSlug,
    projectId: String(project.uuid).trim(),
    states: project.states,
    recipients: normalizedRecipients,
    telegramChatId,
    openAiModel: String($env.PLANE_DAILY_BRIEFING_OPENAI_MODEL || 'gpt-5-mini').trim() || 'gpt-5-mini',
    // Presence is validated above. Keys stay in $env and are never emitted.
    configured: Boolean(planeApiKey && openAiApiKey),
  },
}];

function responseRoot(items) {
  if (!items.length) throw new Error('Store Work Items: Plane returned no response item');
  if (items.length === 1) {
    const value = items[0].json;
    if (value && typeof value === 'object' && value.body !== undefined) {
      const status = Number(value.statusCode || 200);
      if (status < 200 || status >= 300) throw new Error(`Store Work Items: Plane returned HTTP ${status}`);
      return value.body;
    }
    return value;
  }
  return items.map(item => item.json);
}

function extractList(root) {
  if (Array.isArray(root)) return root;
  if (!root || typeof root !== 'object') {
    throw new Error('Store Work Items: unrecognized Plane response shape');
  }
  for (const key of ['results', 'items', 'data', 'work_items', 'issues']) {
    if (Array.isArray(root[key])) return root[key];
  }
  throw new Error('Store Work Items: Plane response does not contain a recognized list');
}

function hasMore(root, count) {
  if (!root || Array.isArray(root) || typeof root !== 'object') return count >= 1000;
  const nextFlag = root.next_page_results;
  if (nextFlag === true || String(nextFlag).toLowerCase() === 'true') return true;
  const total = Number(root.total_results ?? root.total_count ?? root.count);
  if (Number.isFinite(total) && total > count) return true;
  const currentPage = Number(root.current_page ?? root.page);
  const totalPages = Number(root.total_pages);
  if (Number.isFinite(currentPage) && Number.isFinite(totalPages) && currentPage < totalPages) return true;
  if (typeof root.next === 'string' && root.next.trim()) return true;
  // Plane can include next_cursor even on the final page. Cursor presence alone
  // is not evidence that another page exists.
  return count >= 1000;
}

const root = responseRoot($input.all());
const issues = extractList(root);
if (hasMore(root, issues.length)) {
  throw new Error('Store Work Items: Plane work-item page may be truncated at 1000 records; pagination is required before briefing generation');
}
const config = $('Init & Validate Config').first().json;
return [{ json: { ...config, rawIssues: issues } }];

function responseRoot(value) {
  if (value && typeof value === 'object' && value.body !== undefined) {
    const status = Number(value.statusCode || 200);
    if (status < 200 || status >= 300) throw new Error(`Prepare Developer Briefings: Plane module issues returned HTTP ${status}`);
    return value.body;
  }
  return value;
}

function extractList(root) {
  if (Array.isArray(root)) return root;
  if (!root || typeof root !== 'object') {
    throw new Error('Prepare Developer Briefings: unrecognized Plane module-membership response shape');
  }
  for (const key of ['results', 'items', 'data', 'module_issues', 'issues', 'work_items']) {
    if (Array.isArray(root[key])) return root[key];
  }
  throw new Error('Prepare Developer Briefings: Plane module-membership response does not contain a recognized list');
}

function hasMore(root, count) {
  if (!root || Array.isArray(root) || typeof root !== 'object') return count >= 1000;
  const nextFlag = root.next_page_results;
  if (nextFlag === true || String(nextFlag).toLowerCase() === 'true') return true;
  const total = Number(root.total_results ?? root.total_count ?? root.count);
  if (Number.isFinite(total) && total > count) return true;
  const currentPage = Number(root.current_page ?? root.page);
  const totalPages = Number(root.total_pages);
  if (Number.isFinite(currentPage) && Number.isFinite(totalPages) && currentPage < totalPages) return true;
  if (typeof root.next === 'string' && root.next.trim()) return true;
  return count >= 1000;
}

function pairedIndex(item, fallback) {
  const paired = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  const value = paired && paired.item !== undefined ? Number(paired.item) : fallback;
  return Number.isFinite(value) ? value : fallback;
}

function idOf(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string' || typeof value === 'number') return String(value);
  if (typeof value !== 'object') return '';
  return String(value.id || value.uuid || value.member_id || value.user_id || value.assignee_id || '');
}

function collectIds(value, out = []) {
  if (Array.isArray(value)) {
    for (const child of value) collectIds(child, out);
    return out;
  }
  const direct = idOf(value);
  if (direct) out.push(direct);
  if (value && typeof value === 'object') {
    for (const key of ['member', 'user', 'assignee', 'module', 'module_detail']) {
      if (value[key] !== undefined) collectIds(value[key], out);
    }
    for (const key of ['module_id', 'assignee_id', 'member_id', 'user_id']) {
      if (value[key] !== undefined) out.push(String(value[key]));
    }
  }
  return out;
}

function firstString(...values) {
  for (const value of values) {
    if (value !== null && value !== undefined && String(value).trim()) return String(value).trim();
  }
  return '';
}

function stateId(issue) {
  return firstString(idOf(issue.state), issue.state_id, issue.state_uuid, idOf(issue.state_detail));
}

function assigneeIds(issue) {
  const ids = [];
  for (const value of [issue.assignees, issue.assignee_ids, issue.assignee, issue.assignee_id]) {
    collectIds(value, ids);
  }
  return [...new Set(ids.filter(Boolean).map(String))];
}

function moduleIds(issue) {
  const ids = [];
  for (const value of [issue.module, issue.module_id, issue.modules, issue.module_ids, issue.issue_module, issue.issue_modules]) {
    collectIds(value, ids);
  }
  return [...new Set(ids.filter(Boolean).map(String))];
}

function moduleIssueKey(record) {
  for (const value of [record?.issue, record?.issue_id, record?.work_item, record?.work_item_id, record?.issue_detail]) {
    const id = idOf(value);
    if (id) return id;
  }
  if (record && typeof record === 'object' && (record.name || record.title || record.sequence_id !== undefined)) {
    return idOf(record);
  }
  return '';
}

function labelNames(issue) {
  const raw = issue.labels || issue.label_details || [];
  const values = Array.isArray(raw) ? raw : [raw];
  return values.map(value => {
    if (typeof value === 'string') return value;
    return firstString(value?.name, value?.label?.name);
  }).filter(Boolean);
}

function dateRank(dateString) {
  if (!dateString) return 0;
  const due = new Date(`${String(dateString).slice(0, 10)}T23:59:59Z`);
  if (Number.isNaN(due.getTime())) return 0;
  const days = Math.ceil((due.getTime() - Date.now()) / 86400000);
  if (days < 0) return 60;
  if (days <= 3) return 40;
  if (days <= 7) return 20;
  return 0;
}

const stored = $('Store Work Items').first().json;
const moduleRequests = $('Prepare Module Requests').all();
const inputItems = $input.all();
const membershipNamesByIssueId = new Map();
for (let index = 0; index < inputItems.length; index++) {
  const responseItem = inputItems[index];
  if (responseItem.json?.emptyMembership) continue;
  const requestIndex = pairedIndex(responseItem, index);
  if (requestIndex < 0 || requestIndex >= moduleRequests.length) {
    throw new Error(`Prepare Developer Briefings: invalid module pairing index ${requestIndex}`);
  }
  const request = moduleRequests[requestIndex];
  const root = responseRoot(responseItem.json);
  const memberships = extractList(root);
  if (hasMore(root, memberships.length)) {
    throw new Error(`Prepare Developer Briefings: module ${request.json.moduleName} may have more than 1000 work items; pagination is required`);
  }
  for (const membership of memberships) {
    const issueId = moduleIssueKey(membership);
    if (!issueId) continue;
    if (!membershipNamesByIssueId.has(issueId)) membershipNamesByIssueId.set(issueId, new Set());
    membershipNamesByIssueId.get(issueId).add(request.json.moduleName);
  }
}

const moduleNameById = new Map(moduleRequests
  .filter(item => item.json?.moduleId)
  .map(item => [String(item.json.moduleId), item.json.moduleName]));
const stateNameById = new Map(Object.entries(stored.states).map(([name, id]) => [String(id), name]));
const openStateIds = new Set(['backlog', 'todo', 'inProgress', 'inReview'].map(name => String(stored.states[name])));
const allowedRecipientIds = new Set(stored.recipients.map(recipient => recipient.planeUserId));
const priorityWeight = { urgent: 100, high: 80, medium: 40, low: 20, none: 0 };
const stateWeight = { inProgress: 50, todo: 20, backlog: 5, inReview: -20 };
const normalized = [];

for (const issue of stored.rawIssues) {
  if (!issue || typeof issue !== 'object') continue;
  if (issue.archived === true || issue.is_archived === true || issue.archived_at) continue;
  const currentStateId = stateId(issue);
  if (!openStateIds.has(currentStateId)) continue;
  const assigned = assigneeIds(issue).filter(id => allowedRecipientIds.has(id));
  if (!assigned.length) continue;

  const rawPriority = firstString(issue.priority, issue.priority_detail?.key, 'none').toLowerCase();
  const priority = Object.prototype.hasOwnProperty.call(priorityWeight, rawPriority) ? rawPriority : 'none';
  const stateKey = stateNameById.get(currentStateId) || 'unknown';
  const sequence = issue.sequence_id ?? issue.sequence ?? issue.number ?? '';
  const identifier = firstString(issue.identifier, sequence !== '' ? `DEV-${sequence}` : '', issue.name ? `DEV-${idOf(issue).slice(0, 8)}` : 'DEV-?');
  const issueId = idOf(issue);
  const moduleNames = issueId && membershipNamesByIssueId.has(issueId)
    ? [...membershipNamesByIssueId.get(issueId)]
    : [];
  for (const moduleId of moduleIds(issue)) {
    if (moduleNameById.has(moduleId)) moduleNames.push(moduleNameById.get(moduleId));
  }
  const inlineModuleName = firstString(issue.module?.name, issue.module_detail?.name, issue.issue_module?.module?.name);
  if (inlineModuleName) moduleNames.push(inlineModuleName);
  const module = moduleNames.length ? [...new Set(moduleNames)].join(', ') : 'Sem módulo';
  const targetDate = firstString(issue.target_date, issue.due_date);
  const score = (priorityWeight[priority] || 0) + (stateWeight[stateKey] || 0) + dateRank(targetDate);
  const item = {
    identifier,
    name: firstString(issue.name, issue.title, 'Sem título'),
    priority,
    state: stateKey,
    startDate: firstString(issue.start_date),
    targetDate,
    updatedAt: firstString(issue.updated_at, issue.updated),
    labels: labelNames(issue),
    module,
    url: `https://plane.nforensic.site/${encodeURIComponent(stored.workspaceSlug)}/browse/${encodeURIComponent(identifier)}/`,
    score,
  };
  for (const planeUserId of assigned) normalized.push({ planeUserId, item });
}

const stateOrder = { inProgress: 0, todo: 1, backlog: 2, inReview: 3, unknown: 4 };
const results = [];
for (const recipient of stored.recipients) {
  const issues = normalized
    .filter(entry => entry.planeUserId === recipient.planeUserId)
    .map(entry => entry.item)
    .sort((a, b) => b.score - a.score
      || (stateOrder[a.state] ?? 9) - (stateOrder[b.state] ?? 9)
      || String(a.targetDate || '9999-12-31').localeCompare(String(b.targetDate || '9999-12-31'))
      || a.identifier.localeCompare(b.identifier))
    .map(({ score, ...issue }) => issue);
  results.push({
    json: {
      recipient,
      issues,
      hasIssues: issues.length > 0,
      telegramChatId: stored.telegramChatId,
      openAiModel: stored.openAiModel,
    },
  });
}
return results;

const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['overview', 'first_pick', 'top_three', 'attention'],
  properties: {
    overview: { type: 'string' },
    first_pick: {
      type: 'object',
      additionalProperties: false,
      required: ['identifier', 'reason'],
      properties: {
        identifier: { type: 'string' },
        reason: { type: 'string' },
      },
    },
    top_three: {
      type: 'array',
      minItems: 1,
      maxItems: 3,
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['identifier', 'name', 'module', 'reason', 'next_step'],
        properties: {
          identifier: { type: 'string' },
          name: { type: 'string' },
          module: { type: 'string' },
          reason: { type: 'string' },
          next_step: { type: 'string' },
        },
      },
    },
    attention: {
      type: 'array',
      maxItems: 4,
      items: { type: 'string' },
    },
  },
};

const systemPrompt = [
  'És um assistente de planeamento diário para uma equipa de desenvolvimento.',
  'Responde em português de Portugal e usa exclusivamente os dados fornecidos.',
  'Não inventes bloqueios, estados, datas, dependências, nomes ou trabalho.',
  'Escolhe no máximo três tarefas reais e preserva exatamente os respetivos identificadores.',
  'Prioriza urgência e prioridade, prazos vencidos ou próximos, e trabalho já em progresso.',
  'Em regra, trata tarefas Em Revisão como acompanhamento e não como primeira tarefa, salvo evidência explícita nos dados.',
  'Propõe um primeiro passo pequeno, concreto e executável para cada escolha.',
].join(' ');

const todayParts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Lisbon',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).formatToParts(new Date());
const todayByPart = Object.fromEntries(todayParts.map(part => [part.type, part.value]));
const today = `${todayByPart.year}-${todayByPart.month}-${todayByPart.day}`;

return $input.all().map((item, index) => {
  const source = item.json;
  const requestBody = {
    model: source.openAiModel,
    store: false,
    input: [
      { role: 'system', content: [{ type: 'input_text', text: systemPrompt }] },
      {
        role: 'user',
        content: [{
          type: 'input_text',
          text: JSON.stringify({
            developer: source.recipient.displayName,
            today,
            timezone: 'Europe/Lisbon',
            instruction: 'Cria o plano Top 3 para hoje segundo o esquema pedido.',
            issues: source.issues,
          }),
        }],
      },
    ],
    text: {
      format: {
        type: 'json_schema',
        name: 'plane_daily_briefing',
        strict: true,
        schema,
      },
    },
  };
  return { json: { ...source, requestBody }, pairedItem: { item: index } };
});

function pairedIndex(item, fallback) {
  const paired = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  const value = paired && paired.item !== undefined ? Number(paired.item) : fallback;
  return Number.isFinite(value) ? value : fallback;
}

function outputText(body) {
  const chunks = [];
  for (const output of Array.isArray(body?.output) ? body.output : []) {
    for (const content of Array.isArray(output?.content) ? output.content : []) {
      if (content?.type === 'output_text' && typeof content.text === 'string') chunks.push(content.text);
    }
  }
  return chunks.join('').trim();
}

function fallback(source) {
  const selected = source.issues.slice(0, 3);
  const first = selected[0];
  return {
    overview: `Foram encontradas ${source.issues.length} tarefa${source.issues.length === 1 ? '' : 's'} DEV aberta${source.issues.length === 1 ? '' : 's'}.`,
    first_pick: {
      identifier: first.identifier,
      reason: first.state === 'inProgress'
        ? 'Já está em progresso; retomar reduz trabalho em curso.'
        : 'É a tarefa com maior prioridade determinística entre as atribuídas.',
    },
    top_three: selected.map(issue => ({
      identifier: issue.identifier,
      name: issue.name,
      module: issue.module,
      reason: [issue.priority !== 'none' ? `Prioridade ${issue.priority}` : '', issue.targetDate ? `prazo ${issue.targetDate}` : '', issue.state === 'inProgress' ? 'já em progresso' : ''].filter(Boolean).join('; ') || 'Próxima tarefa na ordem definida.',
      next_step: 'Rever o contexto da tarefa e executar a próxima ação concreta descrita no Plane.',
    })),
    attention: ['Análise de IA indisponível; foi aplicada uma ordenação determinística às tarefas reais.'],
  };
}

function validatePlan(plan, source) {
  if (!plan || typeof plan !== 'object' || Array.isArray(plan)) throw new Error('not an object');
  const rootKeys = Object.keys(plan).sort().join(',');
  if (rootKeys !== ['attention', 'first_pick', 'overview', 'top_three'].sort().join(',')) throw new Error('unexpected root properties');
  if (typeof plan.overview !== 'string' || !plan.overview.trim()) throw new Error('missing overview');
  if (!plan.first_pick || typeof plan.first_pick !== 'object') throw new Error('invalid first_pick');
  if (Object.keys(plan.first_pick).sort().join(',') !== ['identifier', 'reason'].sort().join(',')) throw new Error('unexpected first_pick properties');
  if (typeof plan.first_pick.identifier !== 'string' || !plan.first_pick.identifier.trim()) throw new Error('invalid first_pick identifier');
  if (typeof plan.first_pick.reason !== 'string' || !plan.first_pick.reason.trim()) throw new Error('invalid first_pick reason');
  const expectedCount = Math.min(3, source.issues.length);
  if (!Array.isArray(plan.top_three) || plan.top_three.length !== expectedCount) throw new Error('invalid top_three count');
  if (!Array.isArray(plan.attention) || plan.attention.length > 4 || plan.attention.some(note => typeof note !== 'string')) throw new Error('invalid attention');
  const issueById = new Map(source.issues.map(issue => [issue.identifier, issue]));
  if (!issueById.has(plan.first_pick.identifier)) throw new Error('first_pick not supplied');
  const seen = new Set();
  for (const choice of plan.top_three) {
    if (!choice || typeof choice !== 'object') throw new Error('invalid top_three item');
    if (Object.keys(choice).sort().join(',') !== ['identifier', 'module', 'name', 'next_step', 'reason'].sort().join(',')) throw new Error('unexpected top_three properties');
    if (!issueById.has(choice.identifier) || seen.has(choice.identifier)) throw new Error('top_three refers to unknown or duplicate issue');
    for (const key of ['name', 'module', 'reason', 'next_step']) {
      if (typeof choice[key] !== 'string' || !choice[key].trim()) throw new Error(`top_three.${key} invalid`);
    }
    seen.add(choice.identifier);
  }
  if (!seen.has(plan.first_pick.identifier)) throw new Error('first_pick is not in top_three');
  return plan;
}
function clip(value, max) {
  const text = String(value ?? '').trim();
  return text.length <= max ? text : `${text.slice(0, Math.max(0, max - 1)).trimEnd()}…`;
}

function escapeHtml(value) {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function render(source, plan, usedFallback) {
  const issueById = new Map(source.issues.map(issue => [issue.identifier, issue]));
  const stateLabels = { backlog: 'Backlog', todo: 'Por fazer', inProgress: 'Em progresso', inReview: 'Em revisão', unknown: 'Desconhecido' };
  const priorityLabels = { urgent: 'Urgente', high: 'Alta', medium: 'Média', low: 'Baixa', none: 'Sem prioridade' };
  const lines = [
    `<b>Plano diário DEV — ${escapeHtml(source.recipient.displayName)}</b>`,
    escapeHtml(source.recipient.telegramUsername),
    '',
  ];
  if (usedFallback) lines.push('<i>Análise de IA indisponível; prioridade calculada localmente.</i>', '');
  lines.push('<b>Resumo</b>', escapeHtml(clip(plan.overview, 500)), '');
  const first = issueById.get(plan.first_pick.identifier);
  lines.push(
    '<b>Começar por</b>',
    `<a href="${escapeHtml(first.url)}">${escapeHtml(first.identifier)}</a> — ${escapeHtml(clip(first.name, 180))}`,
    escapeHtml(clip(plan.first_pick.reason, 350)),
    '',
    '<b>Top 3</b>',
  );
  plan.top_three.forEach((choice, index) => {
    const issue = issueById.get(choice.identifier);
    lines.push(
      `${index + 1}. <a href="${escapeHtml(issue.url)}">${escapeHtml(issue.identifier)}</a> — <b>${escapeHtml(clip(issue.name, 180))}</b>`,
      `Módulo: ${escapeHtml(clip(issue.module, 100))} · Estado: ${escapeHtml(stateLabels[issue.state] || issue.state)} · Prioridade: ${escapeHtml(priorityLabels[issue.priority] || issue.priority)}`,
      `Porquê: ${escapeHtml(clip(choice.reason, 320))}`,
      `Próximo passo: ${escapeHtml(clip(choice.next_step, 320))}`,
      '',
    );
  });
  if (plan.attention.length) {
    lines.push('<b>Atenção / acompanhamento</b>');
    for (const note of plan.attention.slice(0, 4)) lines.push(`• ${escapeHtml(clip(note, 260))}`);
  }
  const kept = [];
  let size = 0;
  for (const line of lines) {
    if (size + line.length + 1 > 3850) {
      kept.push('…');
      break;
    }
    kept.push(line);
    size += line.length + 1;
  }
  return kept.join('\n').trim();
}

const requestItems = $('Prepare OpenAI Request').all();
return $input.all().map((responseItem, index) => {
  const sourceIndex = pairedIndex(responseItem, index);
  const requestItem = requestItems[sourceIndex] || requestItems[index];
  if (!requestItem) throw new Error(`Validate & Format Briefing: missing request item at index ${sourceIndex}`);
  const source = requestItem.json;
  const envelope = responseItem.json || {};
  const status = Number(envelope.statusCode || 0);
  const body = envelope.body !== undefined ? envelope.body : envelope;
  let plan;
  let usedFallback = false;
  try {
    if (status < 200 || status >= 300) throw new Error(`HTTP ${status || 'unknown'}`);
    if (body?.status !== 'completed') throw new Error(`response status ${body?.status || 'unknown'}`);
    const text = outputText(body);
    if (!text) throw new Error('empty output_text');
    plan = validatePlan(JSON.parse(text), source);
  } catch (error) {
    usedFallback = true;
    plan = fallback(source);
  }
  return {
    json: {
      telegramText: render(source, plan, usedFallback),
      telegramChatId: source.telegramChatId,
      usedFallback,
    },
    pairedItem: { item: sourceIndex },
  };
});

function escapeHtml(value) {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
return $input.all().map((item, index) => {
  const { recipient, telegramChatId } = item.json;
  const text = [
    `<b>Plano diário DEV — ${escapeHtml(recipient.displayName)}</b>`,
    escapeHtml(recipient.telegramUsername),
    '',
    'Sem tarefas DEV abertas atribuídas neste momento.',
  ].join('\n');
  return { json: { telegramText: text, telegramChatId }, pairedItem: { item: index } };
});

function responseRoot(items) {
  if (!items.length) throw new Error('Prepare Module Requests: Plane returned no modules response item');
  if (items.length === 1) {
    const value = items[0].json;
    if (value && typeof value === 'object' && value.body !== undefined) {
      const status = Number(value.statusCode || 200);
      if (status < 200 || status >= 300) throw new Error(`Prepare Module Requests: Plane modules returned HTTP ${status}`);
      return value.body;
    }
    return value;
  }
  return items.map(item => item.json);
}

function extractList(root) {
  if (Array.isArray(root)) return root;
  if (!root || typeof root !== 'object') {
    throw new Error('Prepare Module Requests: unrecognized Plane response shape');
  }
  for (const key of ['results', 'items', 'data', 'modules']) {
    if (Array.isArray(root[key])) return root[key];
  }
  throw new Error('Prepare Module Requests: Plane response does not contain a recognized list');
}

function hasMore(root, count) {
  if (!root || Array.isArray(root) || typeof root !== 'object') return count >= 1000;
  const nextFlag = root.next_page_results;
  if (nextFlag === true || String(nextFlag).toLowerCase() === 'true') return true;
  const total = Number(root.total_results ?? root.total_count ?? root.count);
  if (Number.isFinite(total) && total > count) return true;
  const currentPage = Number(root.current_page ?? root.page);
  const totalPages = Number(root.total_pages);
  if (Number.isFinite(currentPage) && Number.isFinite(totalPages) && currentPage < totalPages) return true;
  if (typeof root.next === 'string' && root.next.trim()) return true;
  // Plane can include next_cursor even on the final page. Cursor presence alone
  // is not evidence that another page exists.
  return count >= 1000;
}

function idOf(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string' || typeof value === 'number') return String(value);
  if (typeof value !== 'object') return '';
  return String(value.id || value.uuid || '');
}

const root = responseRoot($input.all());
const modules = extractList(root);
if (hasMore(root, modules.length)) {
  throw new Error('Prepare Module Requests: Plane module page may be truncated at 1000 records; pagination is required before briefing generation');
}
if (!modules.length) {
  return [{ json: { hasModule: false, moduleId: '', moduleName: 'Sem módulo' } }];
}
return modules.map((module, index) => {
  const moduleId = idOf(module);
  if (!moduleId) throw new Error(`Prepare Module Requests: module ${index + 1} has no id`);
  return {
    json: {
      hasModule: true,
      moduleId,
      moduleName: String(module.name || module.title || 'Sem módulo').trim() || 'Sem módulo',
    },
    // Every module is derived from the single modules response envelope.
    pairedItem: { item: 0 },
  };
});

return $input.all().map((item, index) => ({
  json: { ...item.json, moduleIssues: [], emptyMembership: true },
  pairedItem: { item: index },
}));
